mapper.update:
UPDATE sq_final_delivery
SET owner_type = 'TASK',
    owner_id = #{taskId}
WHERE user_id = #{userId}
  AND source_message_id = #{messageId}
  AND delivery_generation = #{generation}
  AND owner_type = 'RESPONSE'
  AND owner_id = #{executionId}
  AND state = 'OWNED'

UPDATE sq_final_delivery
SET state = 'PUBLISHED',
    published_message_id = #{answerId}
WHERE user_id = #{userId}
  AND source_message_id = #{messageId}
  AND delivery_generation = #{generation}
  AND state = 'OWNED'

UPDATE sq_final_delivery
SET state = 'CLOSED'
WHERE user_id = #{userId}
  AND source_message_id = #{messageId}
  AND delivery_generation = #{generation}
  AND state = 'OWNED'
